# NOTE: run_integration() was given differential bundles that are not recorded in params; add `diff_bundles = list(diff)` if the method needs them.

library(omicsCore)

# ---- Input ---------------------------------------------------------
# read_omics() returns the parsed input and its import report.
input_prot <- read_omics(
  "raw/prot.xlsx",
  type       = "excel",
  omics_type = "proteomics",
  assay_type = "normalized_intensity"
)$input
# read_omics() returns the parsed input and its import report.
input_prot2 <- read_omics(
  "raw/prot2.xlsx",
  type       = "excel",
  omics_type = "proteomics",
  assay_type = "normalized_intensity"
)$input

# ---- Differential analysis -----------------------------------------
diff <- run_diff(
  input_prot,
  method        = "limma",
  analysis_type = "group",
  group_col     = "group",
  control_group = "A",
  case_group    = "B"
)

# ---- Multi-omics integration ---------------------------------------
project <- omics_project(
  name        = "integration",
  experiments = list(prot = input_prot, prot2 = input_prot2)
)
integration <- run_integration(
  project,
  method      = "concordance",
  experiments = c("prot", "prot2"),
  by          = "feature_symbol"
)

# ---- Session -------------------------------------------------------
sessionInfo()
